//! ♻️ Existing cursor allocations retain recursive types and never execute closed-header Drop callbacks.
use super::*;
use std::{alloc::Layout,sync::atomic::{AtomicUsize,Ordering}};
use semio_framework_value_native_storage::NativeOwnedStorage;
struct Bank{left:RetainedCloneGrant,work:u64}
impl Bank{fn new()->Self{let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&f["stock"];Self{left:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},work:s["fuel"].as_u64().unwrap()}}fn grant(&self)->RetainedCloneGrant{assert!(self.left.maximum_items>0&&self.work>0);RetainedCloneGrant{maximum_items:1,..self.left}}fn post(&mut self,p:RetainedCloneProgress,work:u64){assert!(p.fits(self.left));self.left.maximum_items-=p.copied_items;self.left.maximum_copy_bytes-=p.copied_bytes;self.left.maximum_capacity_bytes-=p.retained_capacity_bytes;self.left.maximum_release_bytes-=p.released_bytes;self.work=self.work.checked_sub(work).unwrap();}fn step(&mut self,turn:crate::RetainedWorkOutcome)->RetainedCloneStep{let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());self.post(p,turn.work);turn.result.unwrap()}fn retire<T:crate::retirement::RetireOwned>(&mut self,value:T){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty(){return}let(result,heap)=observe(||owner.step(self.grant()));let work=owner.last_turn_work();let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.step(crate::RetainedWorkOutcome{result,work});}panic!("recursive cursor fixture close depleted its unchanged finite stock")}}
fn observe<R>(f:impl FnOnce()->R)->(R,(usize,usize)){crate::observe_retirement_allocations(f)}
static POISON_DROPS:AtomicUsize=AtomicUsize::new(0);
struct PoisonHeader{byte:u8}
impl Drop for PoisonHeader{fn drop(&mut self){POISON_DROPS.fetch_add(1,Ordering::SeqCst);panic!("closed native header Drop callback was executed")}}
impl NativeReceiver<crate::DslValue,()> for PoisonHeader{
 fn demands(&self,_:RetainedCloneRef<'_,crate::DslValue>,_:usize)->Result<RetirementDemand,ValueError>{panic!("closed header algorithm called")}
 fn advance(&mut self,_:RetainedCloneRef<'_,crate::DslValue>,_:&mut NativeDecodeControl<'_>,_:usize,_:RetainedCloneGrant)->crate::RetainedWorkOutcome<RetainedCloneStep,crate::OriginalReceivingPrimary>{panic!("closed header algorithm called")}
 fn output_ready(&self)->bool{false}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{panic!("closed header output called")}
 fn take(&mut self,_:RetainedCloneGrant)->crate::RetainedWorkOutcome<Option<((),RetainedCloneProgress)>>{panic!("closed header output called")}
 fn begin_close(&mut self){}
 fn close_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{panic!("closed child cursor called")}
 fn close_step(&mut self,_:RetainedCloneGrant)->crate::RetainedWorkOutcome{panic!("closed child cursor called")}
 fn terminal_is_empty(&self)->bool{true}
}
#[test]fn actual_closed_receiver_header_moves_its_existing_allocation_and_skips_poison_drop(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new();let mut storage=NativeOwnedStorage::<PoisonHeader>::empty();let(turn,heap)=observe(||storage.reserve(bank.grant()));let p=bank.step(turn).progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.retained_capacity_bytes,Layout::new::<PoisonHeader>().size());let mut input=Some(PoisonHeader{byte:17});let turn=storage.put_from(&mut input,bank.grant());bank.step(turn);assert!(input.is_none());let pointer=storage.address().unwrap();let mut retired:Option<Box<PoisonHeader>>=None;
 let d=native_receiver_backing_demands::<crate::DslValue,(),_>(&storage,&retired,4096).unwrap();assert_eq!(d.copy_bytes,f["ownedCopyBytes"].as_u64().unwrap()as usize);for denied in[RetainedCloneGrant{maximum_items:0,..bank.grant()},RetainedCloneGrant{maximum_depth:0,..bank.grant()}]{let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(storage.address(),Some(pointer));assert!(retired.is_none());}
 let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,bank.grant()));assert_eq!(turn.work,f["moveWork"].as_u64().unwrap());assert_eq!(heap,(0,0));assert_eq!(bank.step(turn).progress().copied_bytes,0);assert!(storage.terminal_is_empty());assert_eq!(retired.as_ref().unwrap().byte,17);assert_eq!(&**retired.as_ref().unwrap()as*const PoisonHeader as usize,pointer);
 let d=native_receiver_backing_demands::<crate::DslValue,(),_>(&storage,&retired,4096).unwrap();assert_eq!(d.release_bytes,Layout::new::<PoisonHeader>().size());for denied in[RetainedCloneGrant{maximum_items:0,..bank.grant()},RetainedCloneGrant{maximum_depth:0,..bank.grant()},RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..bank.grant()}]{let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert!(retired.is_some());assert_eq!(POISON_DROPS.load(Ordering::SeqCst),0);}
 let(turn,heap)=observe(||close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,bank.grant()));assert_eq!(turn.work,f["freeWork"].as_u64().unwrap());let p=bank.step(turn).progress();assert_eq!(heap,(0,p.released_bytes));assert_eq!(p.released_bytes,Layout::new::<PoisonHeader>().size());assert!(retired.is_none());assert_eq!(POISON_DROPS.load(Ordering::SeqCst),f["poisonDropCalls"].as_u64().unwrap()as usize);assert_eq!(close_native_receiver_backing::<crate::DslValue,(),_>(&mut storage,&mut retired,Default::default()).work,0);
}
#[derive(crate::RetireOwned,crate::NativeReceive,serde::Serialize)]#[value(crate="crate",native_owned="crate")]struct RecursiveNode{children:Vec<RecursiveNode>}
#[derive(serde::Deserialize,serde::Serialize)]struct OracleNode{children:Vec<OracleNode>}
#[test]fn actual_recursive_native_receivers_keep_finite_headers_exact_serde_output_and_cancelled_custody(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let oracle:OracleNode=serde_json::from_value(f["input"].clone()).unwrap();assert_eq!(serde_json::to_value(oracle).unwrap(),f["input"]);for cut in std::iter::once(None).chain(f["cancelCuts"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()))){let mut bank=Bank::new();let source=crate::source_fixture::capture(crate::DslValue::from(&f["input"]),&mut bank,Bank::grant,|bank,p,work,_,_|bank.post(p,work));let(mut receiver,heap)=observe(<RecursiveNode as NativeReceive<crate::DslValue>>::receiver);assert_eq!(heap,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut ready=false;for turn in 0..10000{if receiver.output_ready(){ready=true;break}if cut.is_some_and(|cut|turn>=cut){break}let g=bank.grant();let(result,heap)=observe(||crate::source_fixture::receive(&mut control,g,crate::source_fixture::WorkLoan::new(&bank.work,1),|control|receiver.advance(source.borrow(),control,4096,g)));let p=result.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.post(p,result.work);result.result.unwrap();}if cut.is_none(){assert!(ready);let turn=receiver.take(bank.grant());let p=turn.result.as_ref().unwrap().as_ref().map(|(_,p)|*p).unwrap_or_default();bank.post(p,turn.work);let(value,_)=turn.result.unwrap().unwrap();assert_eq!(serde_json::to_value(&value).unwrap(),f["input"]);bank.retire(value);}receiver.begin_close();for _ in 0..10000{if receiver.terminal_is_empty(){break}let(result,heap)=observe(||receiver.close_step(bank.grant()));let p=result.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.step(result);}assert!(receiver.terminal_is_empty());assert_eq!(observe(||drop(receiver)).1,(0,0));bank.retire(source);}
}
